/* @lc app=leetcode id=3899 lang=kotlin */ class Solution { fun internalAngles(sides: IntArray): DoubleArray = sides.sorted().let { (a, b, c) -> if (a + b <= c) DoubleArray(0) else listOf(Math.toDegrees(Math.acos((b.toDouble() * b + c.toDouble() * c - a.toDouble() * a) / (2.0 * b * c))), Math.toDegrees(Math.acos((a.toDouble() * a + c.toDouble() * c - b.toDouble() * b) / (2.0 * a * c))), Math.toDegrees(Math.acos((a.toDouble() * a + b.toDouble() * b - c.toDouble() * c) / (2.0 * a * b)))).sorted().toDoubleArray() } }